-- Deutsche Bildbeschreibungen, übersetzt aus DescEN.lua (dort von tools/make_desc.py erzeugt).
return {
	["desc.Cadence"] = "Eine junge Frau mit blondem Haar, blauem Kopftuch und roter Tunika. Sie hält eine Fackel hoch, am Gürtel trägt sie einen Dolch.",
	["desc.Melody"] = "Cadences Mutter: rotes Haar unter einem roten Kopftuch, ein grünes Kleid mit Schürze, eine Fackel in der Hand und die Goldene Laute auf dem Rücken.",
	["desc.Aria"] = "Melodys Mutter: eine ältere Frau mit grauem Haar, in einem langen braunen Kleid und Lederrüstung, eine Schaufel in der Hand.",
	["desc.Dorian"] = "Cadences Vater: ein blasser Mann mit langem rotem Haar, grünem Schal und Umhang und goldener Rüstung.",
	["desc.Eli"] = "Cadences Onkel: ein stämmiger Mann mit buschigem rotem Bart, schwarzem Hut und schwerer Schürze.",
	["desc.Monk"] = "Ein kahlköpfiger Mönch in blauer Robe mit gelber Schärpe, der sich mit aneinandergelegten Händen verbeugt.",
	["desc.Dove"] = "Eine sanfte junge Frau mit blondem Haar und türkisfarbenem Kleid, eine weiße Taube auf dem Kopf und eine Blume in der Hand.",
	["desc.Coda"] = "Ein lila, dämonenhaftes Ebenbild von Cadence mit weißen Hörnern, langem Schwanz und einem Dolch.",
	["desc.Bolt"] = "Eine Frau mit dunkler Haut und zu einem Dutt gebundenem lila Haar, in gelber Tunika, die einen Speer schwingt.",
	["desc.Bard"] = "Ein kahler, bärtiger Barde in blauem Hemd und gelber Hose, der singt und dabei Laute spielt.",
	["desc.Nocturna"] = "Eine Vampirin mit blassblauer Haut, spitzen Ohren, rotem Haar und Fledermausflügeln, in weißem Hemd und dunkler Weste, mit einem Krummschwert in der Hand.",
	["desc.Diamond"] = "Ein Tänzer mit dunkler Haut und kurzem schwarzem Haar, in orangefarbener Hose, mitten im Sprung zu einem fliegenden Tritt.",
	["desc.Mary"] = "Eine junge Schäferin mit braunem Haar in zwei Zöpfen und einer Schürze, die einen langen Hirtenstab hält, ein flauschiges Lamm an ihrer Seite.",
	["desc.Tempo"] = "Eine Gestalt mit lila Haut, Metallmaske und weiter Hose, ein goldenes Pendel am Gürtel; aus beiden Händen sprühen knisternde Funken.",
	["desc.Reaper"] = "Eine Gestalt mit Kapuze in lila Robe, mit weißem Totenschädelgesicht und roten Augen, umgeben von schwebenden rosa Seelen.",
	["desc.Coldsteel_Coldsteel"] = "Ein Mädchen mit sehr langen türkisfarbenen Zöpfen, in grauem ärmellosem Oberteil mit türkisfarbener Krawatte und schwarzem Rock, eine Stange Lauch in der Hand.",
	["desc.Goldman_Goldman"] = "Ein Ritter in blauer Rüstung mit goldenen Hörnern am Helm, der eine Schaufelklinge hält, umschwebt von Edelsteinen.",
	["desc.Sync_Chaunter"] = "Ein blasser, geflickter, sackartiger Geist mit Nägeln im Kopf, der eine grüne Laterne trägt.",
	["desc.Sync_Klarinetta"] = "Eine blonde Ritterin in silberner Rüstung mit rot-goldenem Umhang, die ein Langschwert führt.",
	["desc.Sync_Suzu"] = "Eine Kriegerin mit grauer Haut und roter Maske vor dem Mund, in weiß-türkisfarbenen Gewändern, mit einer Stangenwaffe mit langer Klinge.",
	["desc.Slime"] = "Ein hellgrüner Schleimklumpen mit hohlen Augen. Er hüpft auf der Stelle und verlässt nie sein Feld; er versperrt dir nur den Weg.",
	["desc.Slime2"] = "Ein hoher blauer Schleim mit hohlen Augen und aufgerissenem Maul. Er springt zwischen zwei Feldern auf und ab.",
	["desc.Slime3"] = "Ein orangefarbener Schleim mit hohlen Augen. Er läuft ein kleines Quadrat ab: rechts, unten, links, oben, immer wieder.",
	["desc.Slime4"] = "Ein hellblauer Schleim aus Eis. Er läuft diagonal ein kleines Quadrat ab und hinterlässt beim Tod eine Eisfläche.",
	["desc.Slime5"] = "Ein rot-orangefarbener Schleim aus Feuer. Er läuft diagonal ein kleines Quadrat ab und hinterlässt beim Tod heiße Kohlen.",
	["desc.Slime6"] = "Ein leuchtend lila Schleim. Er bewegt sich im Zickzack: rechts, links unten, rechts, links oben, immer wieder.",
	["desc.Slime7"] = "Ein schwarzer Schleim. Er läuft eine Schleife: rechts, links unten, links, rechts oben, immer wieder.",
	["desc.Slime8"] = "Ein weißer Schleim. Er läuft ein großes Quadrat ab: zwei Schritte nach rechts, zwei nach unten, zwei nach links, zwei nach oben.",
	["desc.Motherslime"] = "Ein großer grüner Mutterschleim. Er läuft ein großes Quadrat ab und zerfällt beim Tod in Minischleime.",
	["desc.Tinyslime"] = "Ein winziger grüner Schleim. Er hüpft zufällig umher.",
	["desc.Skeleton"] = "Ein Skelett mit erhobenen Armen. Es läuft auf dich zu und hebt die Arme, kurz bevor es sich bewegt.",
	["desc.Skeleton2"] = "Ein Skelett mit erhobenen Armen, zäher als das weiße. Es läuft auf dich zu; fast besiegt verliert es seinen Kopf und rennt blind geradeaus.",
	["desc.Skeleton4"] = "Ein Skelett aus glitzerndem Kristall. Es läuft auf dich zu und zerspringt in Kristallscherben, wenn es zerstört wird.",
	["desc.Bat"] = "Eine kleine Fledermaus mit ledrigen Flügeln, Reißzähnen und heraushängender Zunge. Sie flattert zufällig umher und beißt jeden, gegen den sie stößt.",
	["desc.Bat3"] = "Eine grüne Fledermaus mit Reißzähnen. Sie flattert zufällig in acht Richtungen, auch diagonal.",
	["desc.Bat4"] = "Eine dunkelgraue Fledermaus mit gelben Augen. Sie flattert zufällig umher, beißt aber immer, wenn du neben ihr stehst.",
	["desc.BatMiniboss"] = "Eine riesige Fledermaus mit Krallenflügeln und einem Maul voller Reißzähne. Sie flattert zufällig umher.",
	["desc.Monkey"] = "Ein lila Affe mit langen Armen. Er springt dich an und klammert sich fest: Du kannst dich nicht bewegen, bis du ihn herunterschlägst, und er kostet dich deinen Münzmultiplikator. Solange er sich festhält, ist er zäher.",
	["desc.Monkey3"] = "Ein grüner Affe mit Stirnband. Er springt dich an und klammert sich fest, und solange er sich festhält, sind deine Richtungen vertauscht.",
	["desc.Monkey4"] = "Ein rosa Zauberaffe mit erhobenen Armen. Er springt dich an und klammert sich fest, und sein Griff teleportiert dich an eine andere Stelle des Levels.",
	["desc.Ghost"] = "Ein blassblauer Geist mit einem Pfeil durch den Kopf und schreiendem Gesicht. Während du dich auf ihn zubewegst, verblasst er und ist unverwundbar; wenn du dich entfernst, wird er wieder fest.",
	["desc.Wraith"] = "Ein rotes Gespenst aus Rauch mit langen, nachwehenden Ranken. Es erscheint aus dem Nichts in deiner Nähe und verfolgt dich.",
	["desc.Zombie"] = "Ein schlurfender Zombie mit blauem Haar, lila Haut und zerrissener Kleidung. Er läuft geradeaus und kehrt um, wenn ihm etwas im Weg ist.",
	["desc.ZombieElectric"] = "Eine Zombiefrau mit lila Afro und gelber Haut, die vor Elektrizität knistert. Sie läuft geradeaus und kehrt um, wenn ihr etwas im Weg ist.",
	["desc.Armadillo"] = "Ein Gürteltier mit schwerem Panzer. Wenn es dich sieht, rollt es sich ein und rollt geradeaus auf dich zu; wo es anhält, bleibt es kurz betäubt liegen.",
	["desc.Armoredskeleton"] = "Ein Skelett, das hinter einem großen Holzschild mit aufgemaltem Totenkopf kauert. Der Schild blockt Treffer von vorn und stößt es nur zurück; greif es von der Seite oder von hinten an.",
	["desc.Armoredskeleton2"] = "Ein Skelett, das hinter einem großen bemalten Schild kauert. Der Schild blockt Treffer von vorn; fast besiegt verliert es seinen Kopf und rennt blind geradeaus.",
	["desc.Armoredskeleton4"] = "Ein Kristallskelett, das hinter einem großen Schild kauert, der Treffer von vorn blockt. Es zerspringt in Kristallscherben, wenn es zerstört wird.",
	["desc.Banshee"] = "Eine große geisterhafte Frau in wallendem Gewand, mit langem weißem Haar, einem Schädel mit Schnabel als Gesicht und langen Krallen. Wird sie getroffen, heult sie, und die Musik um dich herum wird gedämpft.",
	["desc.Clone"] = "Ein Klon von dir mit rot leuchtenden Augen. Bei jedem deiner Schritte bewegt er sich in die Gegenrichtung und spiegelt dich.",
	["desc.Golem"] = "Ein massiger Golem aus Fels, überwuchert von Moos und kleinen Blumen. Sehr langsam und sehr zäh, gräbt er sich durch Wände zu dir durch.",
	["desc.Golem3"] = "Ein massiger Golem aus lila Schlamm, von dem grüner Schleim tropft. Sehr langsam und sehr zäh, gräbt er sich durch Wände zu dir durch.",
	["desc.Mole"] = "Ein blauer Maulwurf mit Sonnenbrille. Er gräbt sich beim Bewegen unter die Erde und taucht zum Angriff auf.",
	["desc.Mushroom"] = "Ein Pilz mit gepunktetem Hut und kleinem Gesicht. Er bewegt sich nie, stößt aber alle paar Beats Sporen aus, die alles um ihn herum verletzen.",
	["desc.MushroomExploding"] = "Ein aufgeblähter Pilz, der schläft, bis er getroffen wird. Einmal geweckt, explodiert er.",
	["desc.MushroomLight"] = "Ein leuchtender Pilz, der die Umgebung erhellt. Er bewegt sich nie.",
	["desc.Nightmare"] = "Ein pferdeartiger Dämon aus dunklem Rauch, mit leuchtenden Augen und Reißzähnen. Er gräbt sich durch Wände zu dir durch.",
	["desc.Tarmonster"] = "Ein dunkelroter Teerklumpen mit einem Auge und zahnigem Grinsen. Er versteckt sich in einer Teerpfütze, bis du nahe kommst, dann packt er dich und zieht dich mit. Beim Tod hinterlässt er Teer.",
	["desc.Wight"] = "Ein grüner Geist aus Rauch mit langen, nachwehenden Ranken. Er erscheint aus dem Nichts in deiner Nähe und verfolgt dich.",
	["desc.Skeletonmage"] = "Ein Skelettmagier mit langem weißem Haar, dunkler Robe und einem Stab, der vor rosa Magie knistert. Aus zwei Feldern Entfernung zieht dich sein Wind direkt neben ihn.",
	["desc.Beetle"] = "Ein Käfer mit einem Panzer wie aus Steinziegeln und feurig orangefarbenen Beinen. Wenn er dich bemerkt, legt er heiße Kohlen um sich herum; ein Treffer auf seinen Panzer stößt ihn zurück und verteilt Kohlen in Kreuzform.",
	["desc.Beetle2"] = "Ein Käfer mit einem Panzer aus blauem Eis. Wenn er dich bemerkt, legt er Eis um sich herum; ein Treffer auf seinen Panzer stößt ihn zurück und verteilt Eis in Kreuzform.",
	["desc.Cauldron"] = "Ein eiserner Kessel voller glühender Kohlen. Er steht einfach nur da; zerbrichst du ihn, verteilen sich heiße Kohlen.",
	["desc.Cauldron2"] = "Ein eiserner Kessel voller Eis. Er steht einfach nur da; zerbrichst du ihn, verteilt sich Eis.",
	["desc.Trapcauldron"] = "Ein eiserner Kessel mit glühenden Kohlen und einem Maul voller Zähne. Er sieht aus wie ein gewöhnlicher Kessel, bis du nahe kommst, dann wacht er auf und beißt. Beim Tod verschüttet er heiße Kohlen.",
	["desc.Trapcauldron2"] = "Ein eiserner Kessel mit Eis und einem Maul voller Zähne. Er sieht aus wie ein gewöhnlicher Kessel, bis du nahe kommst, dann wacht er auf und beißt. Beim Tod verschüttet er Eis.",
	["desc.Fireelemental"] = "Eine lebende Flamme mit Augen. Sie hinterlässt eine Spur heißer Kohlen und gräbt sich durch Wände.",
	["desc.Iceelemental"] = "Ein Wesen aus zackigem Eis. Es hinterlässt eine Eisspur und gräbt sich durch Wände.",
	["desc.Ghast"] = "Ein magentafarbener Geist mit langen, tentakelartigen Armen. Er erscheint aus dem Nichts in deiner Nähe und weicht deinem ersten Treffer aus.",
	["desc.Goblin"] = "Ein Goblin mit langen Ohren und einem Krummmesser. Während du dich auf ihn zubewegst, duckt er sich weg und ist unverwundbar; wenn du dich entfernst, wird er wieder verwundbar.",
	["desc.Hellhound"] = "Ein hagerer, gehörnter Hund mit gelben Schuppen und feuerroter Brust. Beim Tod hinterlässt er heiße Kohlen.",
	["desc.Shovemonster"] = "Ein geisterhafter Rohling mit Schädelgesicht, der sich hinter einer großen Steinplatte versteckt. Er verletzt dich nicht; er schiebt dich weg.",
	["desc.Skeletonknight"] = "Ein Skelett auf einem bleichen Skelettpferd, mit rotem Schild. Sein Schild blockt Treffer von vorn; ein Treffer wirft es vom Pferd, und es kämpft zu Fuß weiter.",
	["desc.Skeletonknight2"] = "Ein Skelett auf einem bleichen Skelettpferd, mit einem Schild, der Treffer von vorn blockt. Ein Treffer wirft es vom Pferd; fast besiegt verliert es seinen Kopf und rennt blindlings los.",
	["desc.Skeletonknight4"] = "Ein Kristallskelett auf einem bleichen Pferd, mit einem Schild, der Treffer von vorn blockt. Ein Treffer wirft es vom Pferd; es zerspringt in Kristallscherben, wenn es zerstört wird.",
	["desc.Yeti"] = "Ein riesiger Yeti mit zotteligem blau-weißem Fell und Schneebällen in den Fäusten. Bei jedem Schritt klatscht er in die Hände und verletzt alles um sich herum; er gräbt sich durch Wände und hinterlässt beim Tod Eis.",
	["desc.Blademaster"] = "Ein Ritter in Plattenrüstung mit Langschwert und Umhang. Er pariert deinen ersten Schlag und schlägt zurück.",
	["desc.Gargoyle"] = "Ein steinerner Gargoyle, der auf einem Sockel kauert. Er bleibt reglos wie eine Statue.",
	["desc.Ghoul"] = "Ein türkisfarbenes Geisterwesen mit wehenden Ranken und breitem Maul. Es erscheint aus dem Nichts in deiner Nähe und weicht deinem ersten Treffer aus.",
	["desc.GoblinBomber"] = "Ein kleiner roter Goblin, der auf einer riesigen Bombe in Schädelform reitet, eine Fackel in der Hand. Sein Angriff ist eine Explosion, und beim Tod lässt er eine brennende Bombe fallen.",
	["desc.SleepingGoblin"] = "Ein schläfriger Goblin mit Kissen und Schaufel. Er döst, bis du nahe kommst, dann wacht er auf und gräbt sich von dir weg.",
	["desc.Harpy"] = "Eine Harpyie: eine Frau mit türkisfarbenem Haar, grün gefiederten Flügeln und Vogelbeinen. Sie fliegt auf dich zu.",
	["desc.Lich"] = "Ein skelettartiger Zauberer in langen Gewändern und Turban, mit einem Stab. Aus zwei Feldern Entfernung belegt er dich mit Verwirrung und vertauscht deine Richtungen.",
	["desc.Mommy"] = "Eine große, in Bandagen gewickelte Mumie, die kleinere Mumien in ihren vielen Armen wiegt. Sie ist langsam und ruft Mumien herbei, die für sie kämpfen.",
	["desc.Mummy"] = "Eine schlurfende, in Bandagen gewickelte Mumie.",
	["desc.Ogre"] = "Ein riesiger grüner Oger mit einem Auge, lila Haar und einem Maul voller Reißzähne, der eine Keule schwingt. Langsam, aber seine Keule zerschmettert die Felder vor ihm.",
	["desc.Pixie"] = "Eine winzige Fee, ein Funkeln aus leuchtend blauen, gelben und rosa Flügeln. Erreicht sie dich, verschwindet sie und heilt dich; triffst du sie, explodiert sie.",
	["desc.Sarcophagus"] = "Ein steinerner Sarg mit einem Kreuz darauf, aus dem knochige Arme greifen. Er bewegt sich nie, lässt aber immer wieder Skelette heraus, bis du ihn zerbrichst.",
	["desc.Spider"] = "Eine große, haarige orangefarbene Spinne mit grünen Augen. Sie lauert in Wänden und springt dich an.",
	["desc.Warlock"] = "Ein Hexer mit Kapuze, eine dunkle Leere statt eines Gesichts und ein Stab voller Funken. Wenn er stirbt, tauscht er den Platz mit dir.",
	["desc.Wraith2"] = "Ein gelb leuchtendes Gespenst, wie eine Flamme mit aufgerissenem Maul. Es erscheint neben dir, packt dich und verflucht deine Gesundheit.",
	["desc.Devil"] = "Ein kleiner Teufel mit einem Widderschädel als Kopf, der aus einem gesprungenen weißen Ei schlüpft. Seine Schale schützt ihn; ist die Schale zerbrochen, bewegt er sich auf jedem Beat.",
	["desc.ElectricMage"] = "Ein Zauberer in langer Robe und Spitzhut, mit einem Stab, auf dem eine leuchtende Glühbirne sitzt. Er schießt Elektrokugeln, die geradeaus fliegen.",
	["desc.ElectricOrb"] = "Eine knisternde Kugel aus Blitzen, die geradeaus fliegt.",
	["desc.Evileye"] = "Ein Klumpen mit Tentakeln, einem riesigen Auge, weiteren Augen auf Stielen und zahnigem Grinsen. Er wartet und stürzt sich dann aus mehreren Feldern Entfernung auf dich.",
	["desc.Gorgon"] = "Eine Gorgone mit Schlangen als Haaren und einem Schlangenschwanz. Erreicht sie dich, lässt sie dich zu Stein erstarren und zerbröckelt.",
	["desc.Metrognome"] = "Ein Gnom mit Schutzbrille, der auf einem goldenen Metronom mit mechanischen Spinnenbeinen reitet. Sein Angriff trifft alle Felder um ihn herum, und wird er getroffen, teleportiert er sich weg.",
	["desc.Orc"] = "Ein muskulöser Ork mit Keule und einem Schild mit Violinschlüssel. Der Schild blockt Treffer von vorn, und jedes Mal, wenn er sich umdreht, verliert er einen Beat.",
	["desc.Skull"] = "Ein riesiger schwebender Schädel mit einem leuchtenden Auge. Triffst du ihn, kommt ein Skelett frei.",
	["desc.WaterBall"] = "Eine schwebende Wasserblase mit Schädelgesicht. Sie heftet sich an dich und platzt, und der Boden wird nass.",
	["desc.WaterBall2"] = "Eine schwebende Teerblase mit Schädelgesicht. Sie heftet sich an dich und platzt und hinterlässt Teer auf dem Boden.",
	["desc.Dragon"] = "Ein großer Drache mit gehörntem Kopf, langen Reißzähnen und Schuppen. Er gräbt sich durch Wände zu dir durch.",
	["desc.Dragon2"] = "Ein großer roter Drache mit Flügeln und langen Reißzähnen. Wenn du in einer Linie mit ihm stehst, speit er Feuer.",
	["desc.Dragon3"] = "Ein großer blauer Drache mit langen Reißzähnen und Hörnern. Wenn du vor ihm stehst, speit er Eis, das dich festfrieren lässt.",
	["desc.Minotaur"] = "Ein Minotaurus mit goldenen Hörnern, gebogen wie eine Lyra, und einem Ring in der Nase. Wenn er dich sieht, stürmt er geradeaus los, durchbricht Wände und ist betäubt, wenn er anhält.",
	["desc.Leprechaun"] = "Ein Kobold mit grünem Kleeblatthut und rotem Bart, der einen Sack Gold trägt. Er flieht vor dir, stiehlt dein Gold, wenn er dich trifft, und verschwindet nach einer Weile.",
	["desc.Fakewall"] = "Ein Stück moosbewachsene Wand, das sich zu einem riesigen Maul voller Reißzähne öffnet. Es sieht aus wie eine Wand, bis du nahe kommst.",
	["desc.Fakewall2"] = "Eine Wand aus gelben Ladenziegeln, die sich zu einem Maul voller Zähne öffnet. Sie sieht aus wie eine Wand, bis du nahe kommst.",
	["desc.Trapchest"] = "Eine Schatztruhe mit einem Maul voller Zähne und einer Zunge. Sie sieht aus wie eine Truhe, bis du nahe kommst, dann wacht sie auf und beißt.",
	["desc.Trapchest4"] = "Eine Holzkiste mit einem Maul voller Zähne. Sie sieht aus wie eine Kiste, bis du nahe kommst.",
	["desc.Trapchest5"] = "Ein Holzfass mit einem Maul voller Zähne. Es sieht aus wie ein Fass, bis du nahe kommst.",
	["desc.Trapchest6"] = "Ein steinerner Schrein mit Flammen obendrauf und einem Maul voller Zähne. Er sieht aus wie ein Schrein, bis du nahe kommst.",
	["desc.Skeletonspearman"] = "Ein Skelett mit einem langen Speer.",
	["desc.Skeletontank"] = "Ein Skelett, versteckt unter einem großen felsigen Panzer. Es stürmt geradeaus los.",
	["desc.Troll"] = "Ein massiger grüner Troll. Wird er getroffen, stürmt er auf dich los.",
	["desc.Toad"] = "Eine kleine grüne Kröte. Sie hüpft auf dich zu.",
	["desc.KingConga"] = "King Conga: ein riesiger grüner, affenartiger Zombie mit rot-goldener Maske, der auf seinem Thron Congas trommelt, während eine Conga-Line aus Zombies um ihn herum tanzt. Verpasst du einen Beat, wird er wütend und verlässt seinen Thron.",
	["desc.ZombieSnake"] = "Ein Zombie, der in King Congas Conga-Line tanzt und seinem Vordermann folgt.",
	["desc.Deathmetal"] = "Death Metal: ein schwarz gekleidetes Skelett mit Kapuze und Sense hinter einem riesigen Totenkopfschild, umschwirrt von blauen Fledermäusen. Der Schild blockt Treffer von vorn, und mit wachsendem Schaden ändert Death Metal seine Taktik.",
	["desc.King"] = "Deep Blues: ein König mit blauer Haut, rotem Bart und Krone, der Kontrabass spielt, an der Spitze einer Schacharmee aus Schädelfiguren. Besiege den König, um zu gewinnen.",
	["desc.Pawn"] = "Ein Schachbauer mit Schädelgesicht. Er marschiert auf deine Seite des Bretts zu und wird zur Dame, wenn er das gegenüberliegende Ende erreicht.",
	["desc.Knight"] = "Ein Schachspringer in Gestalt eines Schädelpferds. Er springt in L-Form.",
	["desc.Bishop"] = "Ein Schachläufer mit Schädelgesicht und Mitra. Er zieht diagonal.",
	["desc.Rook"] = "Ein Schachturm, ein Turm mit Schädelgesicht. Er zieht in geraden Linien.",
	["desc.Queen"] = "Die Schachdame. Sie zieht in jede Richtung.",
	["desc.Coralriff"] = "Coral Riff: ein riesiger dunkelroter Krake, der mit seinen Tentakeln Instrumente spielt: eine Bassgitarre, eine Trompete und mehr. Seine Tentakel steigen um dich herum aus dem Wasser.",
	["desc.Tentacle"] = "Ein Tentakel von Coral Riff, der aus dem Wasser ragt und ein Instrument umklammert.",
	["desc.DeadRinger"] = "Dead Ringer: eine massige Gestalt in goldener Rüstung mit glockenförmigem Helm, die einen Hammer schwingt, einen Gong an der Seite. Er stürmt durch den Raum und läutet die Glocken.",
	["desc.Necrodancer"] = "Der NecroDancer: ein untoter Zauberer mit blauer Haut, langem weißem Bart, rot leuchtenden Augen und rotem Umhang, mit einer goldenen Laute in der Hand. Er erweckt die Toten, damit sie für ihn kämpfen.",
	["desc.Necrodancer2"] = "Der NecroDancer, mit blauer Haut und weißem Bart, den roten Umhang weit ausgebreitet, die Faust erhoben und mit einem Grinsen voller Reißzähne.",
	["desc.LuteDragon"] = "Die Goldene Laute, zum Leben erwacht: ein langer goldener Drache mit rosa Stacheln. Sein Kopf ist der Korpus der Laute, mit einem Maul voller Zähne.",
	["desc.LuteHead"] = "Der Kopf der Goldenen Laute: der Korpus der Laute mit einem Maul voller Zähne. Er spuckt Feuerbälle.",
	["desc.Fortissimole"] = "Fortissimole: ein riesiger Maulwurf in goldener Rüstung mit burgförmigem Helm, der in ein Mikrofon singt, während Skeletttänzer jubeln. Er gräbt sich ein und springt aus dem Boden.",
	["desc.Frankensteinway"] = "Frankensteinway: eine riesige lila Maschine, deren Körper ein Klavier ist, mit gewaltigen Fäusten. Wenn sie sich bewegt, setzt sie den Boden unter Strom.",
	["desc.Conductor"] = "Die Leiterin: eine Wissenschaftlerin mit wildem blondem Haar, Messingschutzbrille und lila Mantel, mit Kabeln und Messingarmen an ihre Maschinen angeschlossen.",
	["desc.Shopkeeper"] = "Ein stämmiger, bärtiger Ladenbesitzer in Turban und Robe, mit einer Stange und einer Laterne über der Schulter. Er singt zur Musik mit, umso lauter, je näher du kommst. Greif ihn nicht an.",
	["desc.ShopkeeperGhost"] = "Der bleiche, leuchtende Geist eines Ladenbesitzers. Er verfolgt dich.",
	["desc.Merlin"] = "Ein kleiner Zauberer mit weißem Haar, großem blauem Spitzhut, blauer Sternenrobe und einem Holzstab.",
	["desc.Hephaestus"] = "Ein muskulöser Schmied in Lederschürze, den Hammer über einem Amboss erhoben.",
	["desc.Medic"] = "Eine große Gestalt mit lila Haut, Hörnern und einer Krone aus Stacheln, mit einem Dreizack und einer Schriftrolle.",
	["desc.Weaponmaster"] = "Ein maskierter Kämpfer in Lila, der eine Klinge wirbeln lässt.",
	["desc.Beastmaster"] = "Ein stämmiger Mann mit Schnurrbart, der eine aufgerollte Peitsche hält.",
	["desc.Bossmaster"] = "Eine starke Frau mit langem orangefarbenem Haar und türkisfarbenem Oberteil, die sich auf einen Hammer stützt.",
	["desc.Janitor"] = "Ein alter Mann mit weißem Bart und grünem Mantel, mit einer Laterne und einem Wischmopp neben einem Eimer.",
	["desc.Diamonddealer"] = "Ein Fuchs in lila Mantel, der einen funkelnden Diamanten hochhält.",
	["desc.Trainer"] = "Ein aufgeschlagenes Buch auf einem Steinsockel: der Kodex.",
	["desc.Transmogrifier"] = "Eine Wissenschaftlerin mit dunklem Haar und Schutzbrille, die leuchtende Tränke hält.",
	["desc.Pawnbroker"] = "Ein grüner Goblin, der auf einem hohen Haufen aus Waffen, Schilden und Schätzen hockt.",
	["desc.Conjurer"] = "Eine blaue Geistergestalt, die über einer Schatztruhe schwebt.",
	["scene.title.necrodancer"] = "Titelbild: Cadence, mit erhobener Fackel und gezücktem Dolch, steht auf einem dunklen Friedhof einem blassblauen Geist mit einem Pfeil durch den Kopf gegenüber. Über ihnen das Logo des Spiels zwischen zwei Schädeln.",
	["scene.title.amplified"] = "Titelbild von Amplified: Nocturna kämpft mit dem Schwert in der Hand gegen einen Skelettmagier mit lila Hut, dessen Stab vor Blitzen knistert.",
	["scene.title.synchrony"] = "Titelbild von Synchrony: Klarinetta mit ihrem Langschwert, Chaunter, der geflickte Geist mit seiner grünen Laterne, und Suzu mit ihrer Stangenwaffe, unter dem Synchrony-Logo.",
	["scene.title.halloween"] = "Halloween-Titelbild mit dem Schriftzug Trick or Treating: Chaunter, der geflickte Geist mit seiner grünen Laterne, und Cadence mit einer Kürbislaterne auf dem Kopf, zwischen leuchtenden Kürbissen.",
	["scene.title.christmas"] = "Weihnachts-Titelbild mit dem Schriftzug Merry Cryptmas: Cadence in rotem Weihnachtsmannmantel mit ihrer Schaufel; hinter ihr füllen ein riesiger weißbärtiger Untoter mit Weihnachtsmannmütze, Geister und ein Sensenmann mit Kapuze den verschneiten Himmel.",
	["scene.zone1"] = "Die Krypta: Böden aus dunkler, festgestampfter Erde und Wände aus Erde voller Wurzeln, Knochen und Schädel, manche aus Steinblöcken. Solange dein Münzmultiplikator aktiv ist, blinkt der Boden im Beat im Schachbrettmuster.",
	["scene.zone2"] = "Böden aus moosgrünem und türkisfarbenem Stein, Wände aus Erde, überwuchert von Blättern und kleinen orangefarbenen Pilzen, und Wände aus hellem Kopfsteinpflaster.",
	["scene.zone3"] = "Diese Tiefe ist zweigeteilt: eine heiße Seite aus rötlichem Fels mit glühend orangefarbenen Böden und eine kalte Seite aus blaugrauem Fels mit eisblauen Böden.",
	["scene.zone4"] = "Die Katakomben: dunkelblaue Böden und Wände aus lila Ziegeln, gesäumt von Skeletten, Schädeln und Bannern.",
	["scene.zone5"] = "Ein Labor: dunkellila Böden mit goldenen und cyanfarbenen Fliesen und Wände aus magentafarbenen Ziegeln voller Rohre, Kabel und Maschinen.",
	["scene.boss"] = "Eine Boss-Arena: ein dunkler Steinboden und Wände aus hellem Stein, besetzt mit Schädeln und Knochen.",
	["scene.boss.NECRODANCER"] = "Die Bühne des NecroDancers: eine grüne Tanzfläche, eingerahmt von riesigen lila Lautsprechern.",
	["cs.intro.1"] = "Nacht auf einem Friedhof. Cadence, eine junge Frau mit blondem Haar, blauem Kopftuch und roter Tunika, klettert mit Fackel und Schaufel zwischen Grabsteinen umher und beginnt dann zu graben.",
	["cs.intro.2"] = "Ihre Schaufel bricht in den Boden ein, und lila Rauch quillt um sie herum hervor.",
	["cs.intro.3"] = "Der Boden gibt nach. Sie stürzt in die Dunkelheit, an greifenden Skeletthänden vorbei.",
	["cs.intro.4"] = "Sie schlägt zwischen Knochen auf dem Steinboden einer Krypta auf und bleibt reglos in einer Blutlache liegen.",
	["cs.intro.5"] = "Lila Licht durchflutet den Raum. Ein untoter Zauberer mit blauer Haut, langem weißem Bart und rotem Umhang ragt über ihr auf: der NecroDancer.",
	["cs.intro.6"] = "Mit seiner Magie reißt er ihr das Herz aus der Brust und hält es grinsend hoch, während es leuchtet.",
	["cs.intro.7"] = "Cadence erwacht auf dem Boden und steht mit ihrer Schaufel auf; lila Rauch steigt aus ihrer Brust.",
	["cs.intro.8"] = "Sie blickt entschlossen nach vorn.",
	["cs.cadence1.1"] = "Ein Holzhaus im Kerzenlicht. Die kleine Cadence lugt um einen Türrahmen.",
	["cs.cadence1.2"] = "Ihr Vater Dorian, mit grüner Mütze, packt eine Karte und Werkzeug in eine Truhe.",
	["cs.cadence1.3"] = "Die kleine Cadence blickt traurig zu Boden, neben ihrem Onkel Eli, einem großen Mann mit rotem Bart und schwarzem Hut.",
	["cs.cadence1.4"] = "Jahre später wühlt die jugendliche Cadence in der alten Truhe ihres Vaters; eine Schaufel lehnt daneben.",
	["cs.cadence1.5"] = "Sie zieht seine Notizen und eine Karte heraus und grinst.",
	["cs.cadence1.6"] = "Onkel Eli sieht stirnrunzelnd von der Tür aus zu, während Cadence wegschaut.",
	["cs.cadence1.7"] = "Cadence hält die Karte fest umklammert, entschlossen.",
	["cs.cadence2.1"] = "Eine Beerdigung auf einem grünen Hügel. Trauernde in dunklen Kleidern stehen an einem roten, mit Blumen bedeckten Sarg. Die kleine Cadence singt daneben.",
	["cs.cadence2.2"] = "Hinter ihr zeigt Onkel Eli anklagend mit dem Finger auf ihren Vater Dorian.",
	["cs.cadence2.3"] = "Von oben gesehen breitet Dorian flehend die Hände aus, während Eli sich über ihm aufbaut.",
	["cs.cadence2.4"] = "Nahaufnahme: Dorian schaut angespannt weg; Elis Faust ist geballt.",
	["cs.cadence2.5"] = "Cadence kehrt ihnen den Rücken zu und legt die Hand auf den Sarg, während rote Blütenblätter vorbeiwehen.",
	["cs.cadence3.1"] = "Ein sonniges Picknick an einem See. Eine Frau mit rotem Kopftuch, Melody, spielt Laute, während Dorian die kleine Cadence herumwirbelt. In der Nähe grast ein Pferd.",
	["cs.cadence3.2"] = "Die kleine Cadence tanzt und lacht; hinter ihr umarmen sich ihre Eltern.",
	["cs.cadence3.3"] = "Später liegt Melody krank im Bett, mit verbundenem Kopf und dunklen Flecken auf dem Arm. Dorian hält ihre Hand.",
	["cs.cadence3.4"] = "Dorian wendet sich bedrückt ab, während die kleine Cadence von der Tür aus zusieht.",
	["cs.cadence4.1"] = "Cadence kniet über einem blassen Mann mit langem rotem Haar in goldener Rüstung: ihrem Vater Dorian.",
	["cs.cadence4.2"] = "In einer Kryptahalle mit lila Bögen breitet der NecroDancer die Arme aus, eine goldene Laute in einer Hand.",
	["cs.cadence4.3"] = "Eine Flamme in seiner anderen Hand verwandelt sich in Cadences schlagendes Herz, und er hält es hoch, um sie zu verhöhnen.",
	["cs.cadence4.4"] = "Cadence, mit Schaufel und Dolch, steht Seite an Seite mit Dorian, der einen schweren goldenen Hammer hält.",
	["cs.cadence5.1"] = "Der NecroDancer liegt besiegt am Boden. Dorian in goldener Rüstung hält seine goldene Laute; hinter ihm leuchtet Cadence in lila Licht.",
	["cs.cadence5.2"] = "Cadence, die Schaufel in der Hand, sieht ihren Vater an, als er mit der Laute davongeht.",
	["cs.cadence5.3"] = "Draußen, unter einem grünen Mond, kommen Cadence und Dorian zwischen Grabsteinen und verdrehten Wurzeln hervor; Dorian trägt die Laute.",
	["cs.melody0.1"] = "Nacht auf dem Friedhof unter einem grünen Mond. Dorian spielt die Goldene Laute über einem offenen Sarg, während Cadence daneben kniet. Im Sarg liegt eine Frau mit rotem Haar: Melody.",
	["cs.melody0.2"] = "Melody reißt in einem lila Lichtblitz die Augen auf.",
	["cs.melody0.3"] = "Sie setzt sich im Sarg auf, und Cadence und Dorian lächeln.",
	["cs.melody0.4"] = "Eine Vision des besiegten NecroDancers, aus dem lila Rauch strömt.",
	["cs.melody0.5"] = "Zu Hause nimmt Melody, mit rotem Kopftuch und grünem Kleid, eine Schaufel und die Goldene Laute an sich.",
	["cs.melody0.6"] = "Mit hoch erhobener Fackel steigt sie einen Steinschacht hinab in die Krypta, während grüne Tentakel aus den Wänden greifen.",
	["cs.melody1.1"] = "Ein Krankenzimmer. Melody liegt blass im Bett, eine rote Rose auf der Decke. Dorian, mit grüner Mütze, sitzt neben ihr und hält ihre Hand.",
	["cs.melody1.2"] = "Nahaufnahme: Dorian beugt sich über sie, mit verengten, harten Augen, während sie geschwächt und mit verbundenem Kopf daliegt.",
	["cs.melody2.1"] = "In einer Bauernhausküche hebt eine grauhaarige Frau mit einer goldenen Laute, Aria, sanft das Kinn der jungen Melody an.",
	["cs.melody2.2"] = "Später geht Arias dunkle Silhouette zur Tür hinaus, während Melody mit dem Rücken zu ihr und gesenktem Kopf dasteht.",
	["cs.melody3.1"] = "Ein Dorf in der Abenddämmerung. Aria spielt ihre goldene Laute am Bett eines kranken Mannes, während die junge Melody ihn pflegt.",
	["cs.melody3.2"] = "Ein Dorfbewohner mit Fackel schreit und zeigt auf Aria in einem Türrahmen; andere versammeln sich mit Mistgabeln und Sensen.",
	["cs.melody3.3"] = "Melody und Aria stehen mit der Laute beieinander, umringt von den Mistgabeln des Mobs, in einem grellen lila Lichtschein.",
	["cs.melody4.1"] = "In der Kryptahalle spielt Melody die Goldene Laute über dem NecroDancer, der in seinem roten Umhang am Boden liegt.",
	["cs.melody4.2"] = "Langsam erhebt er sich: blaue Haut, rote Augen, ausgestreckte Klauenhände.",
	["cs.melody4.3"] = "Von oben gesehen spielt Melody weiter, während der NecroDancer auf sie zukriecht.",
	["cs.melody4.4"] = "Nahaufnahme des fauchenden Gesichts des NecroDancers, seine Augen glühen rot.",
	["cs.melody4.5"] = "Nahaufnahme: Melody zupft ruhig die Laute und hört nicht auf.",
	["cs.melody4.6"] = "Der NecroDancer bäumt sich auf und schreit vor Wut, in einem grellen lila Lichtschein.",
	["cs.melody5.1"] = "Der NecroDancer taumelt rückwärts auf einen offenen Steinsarg zu.",
	["cs.melody5.2"] = "Ein lila Lichtblitz: Eine grauhaarige Frau in lila Kleid stößt ihm von hinten einen Dolch in den Leib, während Melody zusieht.",
	["cs.melody5.3"] = "Sein roter Umhang sinkt zu Füßen der Frau zu Boden.",
	["cs.melody5.4"] = "In der düsteren Krypta wendet sich Melody der grauhaarigen Frau zu, die noch immer den Dolch hält.",
	["cs.nocturna1.1"] = "Eine Krypta voller seltsamer Maschinen. Nocturna, eine Vampirin mit blassblauer Haut, rotem Haar und Fledermausflügeln, hält neben einem riesigen Schädel eine Fackel hoch.",
	["cs.nocturna1.2"] = "Ein Skelett lehnt zusammengesunken an Rohren und Messgeräten, während ein Funke an einem Kabel entlangläuft.",
	["cs.nocturna1.3"] = "Von unten gesehen steht Nocturna aufrecht mit der Fackel da, die Flügel ausgebreitet.",
	["cs.nocturna1.4"] = "Sie fliegt eine dunkle Treppe hinab, die Fackel voran.",
	["cs.nocturna2.1"] = "Nocturna hält in einem Raum voller Maschinen und leuchtender Anzeigen eine Fackel hoch und greift nach der Wand.",
	["cs.nocturna2.2"] = "Sie geht einen langen Metallkorridor entlang, gesäumt von Kabeln und Lichtern.",
	["cs.nocturna2.3"] = "Nahaufnahme: Ihre blaue Hand berührt dicke Kabel, die vor gelber Elektrizität knistern.",
	["cs.nocturna2.4"] = "Von oben gesehen folgt sie den leuchtenden Kabeln über den Boden.",
	["cs.nocturna2.5"] = "Sie fliegt mit ausgebreiteten Flügeln weiter, durch einen von Feuer erhellten Tunnel.",
	["cs.nocturna3.1"] = "Ein Skelett mit Helm, an die Maschinen angeschlossen, sitzt zusammengesunken zwischen gelben Funken.",
	["cs.nocturna3.2"] = "Nahaufnahme: Nocturna mustert es unbeeindruckt.",
	["cs.nocturna3.3"] = "Sie hockt sich neben das Skelett und zieht an den Kabeln in seinem Rücken.",
	["cs.nocturna3.4"] = "Sie hält das Kabelbündel in beiden Händen und ballt dann die Fäuste.",
	["cs.nocturna3.5"] = "Sie geht allein einen langen Korridor entlang; ein weiteres verkabeltes Skelett hängt an der Wand.",
	["cs.nocturna4.1"] = "Eine Rückblende: Eine junge Frau mit brauner Haut und lockigem braunem Haar schreit und streckt die Hand aus, während ein blauer Vampir mit roten Augen sie in den Hals beißt; hinter ihnen eine Kirche unter lila Himmel.",
	["cs.nocturna4.2"] = "Ihre Haut wird blassblau und ihr Haar rot, während hinter ihr Feuer brennt.",
	["cs.nocturna4.3"] = "In einem Wald aus weißen Birken hockt die geflügelte Nocturna über einem am Boden liegenden Tier, während rote Augen aus der Dunkelheit zusehen.",
	["cs.nocturna4.4"] = "Ein großer Vampir mit langem, wallendem rotem Haar kriecht aus der Dunkelheit auf sie zu.",
	["cs.nocturna4.5"] = "Nahaufnahme: Nocturna betrachtet ihre blutigen Hände und ballt sie dann zu Fäusten.",
	["cs.nocturna5.1"] = "Ein Labor voller Maschinen. Ein riesiger lila mechanischer Körper liegt auf einem Tisch; seine Brust leuchtet, Funken sprühen.",
	["cs.nocturna5.2"] = "Nocturna, ein Schwert in der Hand, tritt darauf zu.",
	["cs.nocturna5.3"] = "Eine Frau in lila Mantel und Messingschutzbrille, mit wildem blondem Haar und blauen Lippen, wendet sich von ihrer Arbeit ab: die Leiterin.",
	["cs.nocturna5.4"] = "Nocturna richtet durch den Dampf ihr Schwert auf sie.",
	["cs.nocturna5.5"] = "Die Leiterin verschränkt unbeeindruckt die Arme.",
	["cs.nocturna5.6"] = "Sie blickt mit einem verschlagenen Lächeln auf Nocturna herab.",
	["cs.nocturna5.7"] = "Sie tritt an eine Maschine und hebt eine goldene Laute heraus.",
	["cs.nocturna5.8"] = "Die Laute lodert in ihren Händen in gelbem Licht auf.",
	["cs.nocturna5.9"] = "Nocturna hebt ihr Schwert.",
	["cs.nocturna5.10"] = "Nocturna springt auf sie zu, während Blitze aus der Laute hervorbrechen.",
	["cs.nocturna6.1"] = "Nocturna steht mit dem Schwert in der Hand über der zerstörten Maschine der Leiterin; Rauch steigt auf.",
	["cs.nocturna6.2"] = "Sie betrachtet ihre offene Hand.",
	["cs.nocturna6.3"] = "Rote Energie wirbelt um sie herum. Ihre Augen glühen rot, und sie grinst mit gebleckten Reißzähnen.",
	["cs.nocturna6.4"] = "Sie packt ein goldenes Gerät, das vor Blitzen knistert, hebt es schreiend hoch und schmettert es in einen Spiegel.",
	["cs.nocturna6.5"] = "Sie ergreift die Goldene Laute und hebt sie über den Kopf, mit lodernden Augen.",
	["cs.nocturna6.6"] = "Ihre Augen werden wieder normal. Sie zögert.",
	["cs.nocturna6.7"] = "Im gesprungenen Spiegel sieht sie ihr menschliches Ich: eine Frau mit brauner Haut, lockigem braunem Haar und runder Brille.",
	["cs.nocturna6.8"] = "Sie senkt die Laute und hält sie ruhig; ihre Augen sind jetzt golden.",
	["cs.nocturna6.9"] = "Licht fällt von oben durch einen Schacht. Ihre Silhouette steigt darin auf und ist verschwunden.",
	["cs.introDlc.1"] = "Nacht auf einem Friedhof unter Vollmond und lila Himmel. Eine Ratte mit rosa leuchtenden Augen schleicht einen Ast entlang.",
	["cs.introDlc.2"] = "Blätter wehen über die Gräber.",
	["cs.introDlc.3"] = "Vor einer Gruft erhebt sich eine dunkle Klauenhand aus der Erde, während darüber eine Gestalt mit roten Augen hockt.",
	["cs.introDlc.4"] = "Eine Gestalt mit Kapuze und rot leuchtenden Augen ragt in der Dunkelheit auf.",
	["cs.introDlc.5"] = "Nahaufnahme: rote Vampiraugen und ein verschlagenes Lächeln.",
	["cs.introDlc.6"] = "Eine geflügelte Silhouette landet neben einer alten steinernen Gruft.",
	["cs.introDlc.7"] = "Nocturna steht unter dem Vollmond, die Hände in die Hüften gestemmt, die Fledermausflügel ausgebreitet.",
	["cs.introDlc.8"] = "Sie stampft auf, und die Steinplatte der Gruft zerbricht.",
	["cs.introDlc.9"] = "Sie späht in die zerbrochene Gruft, wo ein rosa leuchtender Gang hinabführt.",
	["cs.introDlc.10"] = "Sie taucht hinein, und hinter ihr krallen sich tote Hände aus der Erde.",
	["cs.aria0.1"] = "In der Krypta spielt Melody die Goldene Laute. Hinter ihr steht ihre Mutter Aria: graues Haar, ein lila Kleid, braune Lederrüstung, einen Dolch in der Hand.",
	["cs.aria0.2"] = "Nahaufnahme: Melody funkelt sie wütend an.",
	["cs.aria0.3"] = "Aria blickt beschämt zu Boden, vom Fackelschein beleuchtet.",
	["cs.aria0.4"] = "Melodys Wut weicht Traurigkeit; sie spielt weiter.",
	["cs.aria0.5"] = "Aria streckt ihrer Tochter die offene Hand entgegen.",
	["cs.aria1.1"] = "Aria spielt die Goldene Laute vor einem Torbogen aus Stein und Schädeln.",
	["cs.aria1.2"] = "In einem dunklen, überwucherten Schrein hebt sie die Laute neben einem Steinsockel, auf dem eine rosa Flamme brennt.",
	["cs.aria1.3"] = "Die Laute erwacht in ihren Händen zum Leben: Ihr Hals rollt sich wie ein goldener Drache ein und ihr wachsen Klauen, während die rosa Flamme auflodert.",
	["cs.aria2.1"] = "Eine Taverne. Ein junger Barde mit rotem Bart und blauem Hemd spielt auf einer kleinen Bühne Laute, während die Zecher ihn ignorieren.",
	["cs.aria2.2"] = "Später, in einem dunklen Wald, schirmt derselbe Barde, mit Rucksack und Wanderstab, seine Augen vor einer goldenen Laute ab, die auf einem Stein leuchtet.",
	["cs.aria3.1"] = "Der Barde Octavian spielt die Goldene Laute für eine Armee von Monstern: einen riesigen roten Minotaurus mit goldenen Hörnern, einen grünen Schleim voller Knochen und Skelette, die Schwerter schwingen.",
	["cs.aria3.2"] = "Lange zuvor geht Aria mit Schaufel und Fackel durch die leere Krypta.",
	["cs.aria3.3"] = "Nahaufnahme: Octavian, jetzt blauhäutig und untot, mit langem weißem Bart und rotem Umhang, spielt die Laute mit müden, leeren Augen.",
	["cs.aria3.4"] = "Die Laute gleitet ihm aus den Händen und verschwindet in der Dunkelheit.",
	["cs.aria4.1"] = "Aria, eine Schaufel an der Seite, spielt die Goldene Laute über einem offenen Steinsarg, in dem der NecroDancer liegt.",
	["cs.aria4.2"] = "Blaue Hände packen den Rand des Sargs, als er erwacht.",
	["cs.aria4.3"] = "Der NecroDancer steht auf und greift nach der Laute, während Aria weiterspielt.",
	["cs.aria4.4"] = "In einem grellen lila Lichtschein hält Aria die Laute hin, und seine blauen Hände schließen sich darum.",
	["cs.aria4.5"] = "Er reißt die Laute an sich und stößt Aria zur Seite; seine Augen glühen rot.",
	["cs.aria5.1"] = "Im überwucherten Schrein schirmt Aria ihre Augen ab, während lila Blitze aus dem Sockel um die Goldene Laute strömen.",
	["cs.aria5.2"] = "Sie schmettert die Laute auf den Sockel, und Strahlen aus lila Licht brechen hervor.",
	["cs.aria5.3"] = "Lila Blitze umhüllen sie, und sie sinkt gegen den Stein.",
	["cs.aria5.4"] = "Bei Sonnenuntergang auf einem Hügel steht Cadence vor einem Grabstein, in den der Name Aria gemeißelt ist.",
	["cs.aria5.5"] = "Melody und Dorian gesellen sich Arm in Arm zu ihr, während die Sonne untergeht.",
}
